1: import Vue from 'vue'
2: import BranchOneDialog from '@/views/supervision/agreement/xy/components/BranchOneDialog.vue'
3: 
4: let unionBankBranchOpening = false
5: 
6: /**
7:  * 开户网点 / 联行选择（关键字，可选左侧银行树）
8:  * 使用 BranchOneDialog + zs-select-dialog 实现，对外提供函数式 Promise API
9:  */
10: export function openUnionBankBranchSelect(vm, options = {}) {
11:   if (unionBankBranchOpening) {
12:     return Promise.reject('already_open')
13:   }
14: 
15:   const active = document.activeElement
16:   if (active && typeof active.blur === 'function') {
17:     active.blur()
18:   }
19: 
20:   return new Promise((resolve, reject) => {
21:     unionBankBranchOpening = true
22: 
23:     const props = {
24:       visible: true,
25:       title: options.title || '选择开户网点',
26:       workBankId: options.workBankId,
27:       url: options.url || '/system/unionBank/page',
28:       bankName: options.bankName,
29:       bankCode: options.bankCode,
30:       showTree: options.showTree ?? false,
31:       showTable: options.showTable ?? true,
32:       tableScroll: options.tableScroll ?? false,
33:       outQuery: options.outQuery || options.filterParams || {}
34:     }
35: 
36:     const instance = new (Vue.extend(BranchOneDialog))({
37:       parent: vm,
38:       propsData: props,
39:       store: vm.$store,
40:       router: vm.$router
41:     })
42: 
43:     const releaseOpeningLock = () => {
44:       unionBankBranchOpening = false
45:     }
46: 
47:     const cleanup = () => {
48:       releaseOpeningLock()
49:       try {
50:         if (instance && !instance._isDestroyed) {
51:           instance.$destroy()
52:         }
53:         if (instance.$el?.parentNode === document.body) {
54:           document.body.removeChild(instance.$el)
55:         }
56:       } catch (e) {
57:         console.warn('openUnionBankBranchSelect cleanup:', e)
58:       }
59:     }
60: 
61:     instance.$on('setData', (row) => {
62:       cleanup()
63:       resolve(row)
64:     })
65:     instance.$on('update:visible', (visible) => {
66:       if (!visible) {
67:         cleanup()
68:         reject('cancel')
69:       }
70:     })
71: 
72:     instance.$mount()
73:     document.body.appendChild(instance.$el)
74:   })
75: }

