import { chromium } from 'playwright'

const BASE = 'http://58.210.252.230:9002'
const browser = await chromium.launch({ headless: true })
const page = await browser.newPage({ viewport: { width: 1798, height: 949 } })

page.on('response', async (res) => {
  const u = res.url()
  if (/code|captcha|login/i.test(u)) {
    let body = ''
    try { body = (await res.text()).slice(0, 400) } catch {}
    console.log('RESP', res.status(), u, body)
  }
})

await page.goto(BASE + '/', { waitUntil: 'networkidle', timeout: 60000 })
console.log('URL', page.url())
console.log('TITLE', await page.title())
const inputs = await page.locator('input').evaluateAll(els => els.map(e => ({ ph: e.placeholder, type: e.type, cls: e.className })))
console.log('INPUTS', JSON.stringify(inputs))
const imgs = await page.locator('img').evaluateAll(els => els.slice(0, 10).map(e => ({ src: (e.src || '').slice(0, 160), cls: e.className })))
console.log('IMGS', JSON.stringify(imgs))
const btns = await page.locator('button').evaluateAll(els => els.slice(0, 12).map(e => e.innerText.trim()))
console.log('BUTTONS', JSON.stringify(btns))
const bodyText = (await page.locator('body').innerText()).slice(0, 600)
console.log('BODY', bodyText)
await browser.close()

