import fs from 'fs'
import { chromium } from 'playwright'

const BASE = 'http://58.210.252.230:9002'
const TMP = '.tmp-bug6084'
const answersFile = `${TMP}/captcha-answers.txt`
const resultFile = `${TMP}/repro-result.json`
for (const f of [answersFile, resultFile, `${TMP}/captcha.jpg`]) { try { fs.unlinkSync(f) } catch {} }

const browser = await chromium.launch({ headless: true })
const page = await browser.newPage({ viewport: { width: 1798, height: 949 } })

let codeBody = null
page.on('response', async (res) => {
  if (res.url().includes('/api/v3.0/code')) {
    try {
      codeBody = await res.json()
      console.log('CODE_BODY', JSON.stringify({ code: codeBody.code, msg: codeBody.msg, captchaOnOff: codeBody.captchaOnOff, uuid: codeBody.uuid, keys: Object.keys(codeBody) }))
    } catch {}
  }
})

await page.goto(BASE + '/', { waitUntil: 'networkidle', timeout: 60000 })
await page.waitForSelector('input[placeholder="请输入验证码"]', { timeout: 20000 })
const src = await page.locator('img.login-code-img').getAttribute('src')
fs.writeFileSync(`${TMP}/captcha.jpg`, Buffer.from(String(src).split(',')[1], 'base64'))
console.log('CAPTCHA_SAVED')

const deadline = Date.now() + 420000
let answers = []
while (Date.now() < deadline) {
  if (fs.existsSync(answersFile)) {
    const txt = fs.readFileSync(answersFile, 'utf8').trim()
    if (txt) { answers = txt.split(/[\s,]+/).filter(Boolean); break }
  }
  await new Promise(r => setTimeout(r, 400))
}
console.log('ANSWERS', JSON.stringify(answers))
if (!answers.length) { await browser.close(); process.exit(1) }

let loggedIn = false
for (const ans of answers) {
  await page.fill('input[placeholder="请输入用户名/身份证号码/手机号码"]', 'zsbase')
  await page.fill('input[placeholder="请输入用户密码"]', 'ZS001Aa!')
  await page.fill('input[placeholder="请输入验证码"]', ans)
  await page.getByRole('button', { name: /登\s*录/ }).first().click()
  try {
    await page.waitForURL(u => !String(u).includes('/login'), { timeout: 6000 })
    loggedIn = true
    console.log('LOGIN_OK_WITH', ans, page.url())
    break
  } catch {
    const msg = (await page.locator('.el-message, .el-message-box, body').first().innerText().catch(() => '')).replace(/\s+/g, ' ').slice(0, 160)
    console.log('TRY_FAIL', ans, msg)
  }
}
if (!loggedIn) { console.log('LOGIN_FAILED'); await browser.close(); process.exit(1) }

const target = BASE + '/#/spfzjjg/zjjg/ACCOUNT_OPEN/account/add?formMode=add&backUrl=%2Fspfzjjg%2Fzjjg%2FACCOUNT_OPEN%2Faccount'
await page.goto(target, { waitUntil: 'networkidle', timeout: 60000 })
await page.waitForTimeout(2000)
console.log('PAGE_URL', page.url())
console.log('PAGE_TEXT', (await page.locator('body').innerText()).replace(/\s+/g, ' ').slice(0, 500))

const fieldInfo = await page.locator('input[placeholder="点击选择开户网点"]').evaluateAll(els => els.map(e => ({ disabled: e.disabled, readonly: e.readOnly })))
console.log('FIELD', JSON.stringify(fieldInfo))
if (!fieldInfo.length || fieldInfo[0].disabled) {
  const injected = await page.evaluate(() => {
    const root = document.querySelector('#app')?.__vue__
    if (!root) return 'no-root'
    const stack = [root]; let found = null
    while (stack.length) {
      const vm = stack.pop()
      if (vm && typeof vm.showVisionOfBank === 'function') { found = vm; break }
      ;((vm && vm.$children) || []).forEach(c => stack.push(c))
    }
    if (!found) return 'no-vm'
    if (!found.form.bankName) found.form.bankName = '中国建设银行苏州分行营业部'
    if (!found.form.bankId) found.form.bankId = '1'
    return 'ok'
  })
  console.log('INJECT', injected)
  await page.waitForTimeout(500)
}

const field = page.locator('input[placeholder="点击选择开户网点"]').first()
try { await field.click({ timeout: 10000 }) } catch (e) { console.log('CLICK_ERR', String(e).slice(0, 200)) }
await page.waitForTimeout(3000)

const cnt = await page.locator('.el-dialog__wrapper.zs-dialog.zs-select-dialog').count()
console.log('DIALOG_COUNT', cnt)
const metrics = await page.evaluate(() => {
  const wrap = document.querySelector('.el-dialog__wrapper.zs-dialog.zs-select-dialog')
  if (!wrap) return { error: 'no-dialog' }
  const dlg = wrap.querySelector('.el-dialog')
  const body = wrap.querySelector('.el-dialog__body')
  const right = wrap.querySelector('.dialog-right')
  const tableWrap = wrap.querySelector('.select-dialog-table-wrap')
  const pag = wrap.querySelector('.zs-pagination') || wrap.querySelector('.el-pagination')
  const box = (el) => el ? { sh: el.scrollHeight, ch: el.clientHeight, oh: el.offsetHeight, top: Math.round(el.getBoundingClientRect().top), bottom: Math.round(el.getBoundingClientRect().bottom) } : null
  const r = pag ? pag.getBoundingClientRect() : null
  return {
    wrapperClass: wrap.className,
    dialogClass: dlg?.className,
    dialog: box(dlg), body: box(body), right: box(right), tableWrap: box(tableWrap), pag: box(pag),
    pagInView: r ? (r.bottom <= innerHeight + 1 && r.top >= 0) : null,
    pagText: pag ? pag.innerText.replace(/\s+/g, ' ').slice(0, 140) : null,
    viewport: { w: innerWidth, h: innerHeight },
    bodyOverflowY: body ? getComputedStyle(body).overflowY : null,
    bodyMaxHeight: body ? getComputedStyle(body).maxHeight : null,
    rightOverflowY: right ? getComputedStyle(right).overflowY : null,
    rightFlex: right ? getComputedStyle(right).flex : null,
    tableWrapFlex: tableWrap ? getComputedStyle(tableWrap).flex : null,
    tableWrapOverflow: tableWrap ? getComputedStyle(tableWrap).overflow : null,
    dialogHeight: dlg ? getComputedStyle(dlg).height : null,
    dialogMaxHeight: dlg ? getComputedStyle(dlg).maxHeight : null,
    viewportVar: dlg ? getComputedStyle(dlg).getPropertyValue('--zs-dialog-viewport-height') : null
  }
})
console.log('METRICS', JSON.stringify(metrics))
fs.writeFileSync(resultFile, JSON.stringify(metrics, null, 2))
await page.screenshot({ path: `${TMP}/repro.png`, fullPage: false })
console.log('SCREENSHOT', `${TMP}/repro.png`)
await browser.close()

