import fs from 'fs'
import { chromium } from 'playwright'

const BASE = 'http://58.210.252.230:9002'
const TMP = '.tmp-bug6084'
const stateFile = `${TMP}/state.json`
const browser = await chromium.launch({ headless: true })
const context = await browser.newContext({ viewport: { width: 1798, height: 949 } })
if (fs.existsSync(stateFile)) {
  try { await context.addCookies(JSON.parse(fs.readFileSync(`${TMP}/cookies.json`, 'utf8'))) } catch {}
}
const page = await context.newPage()

const dismiss = async () => {
  const btn = page.locator('.el-message-box__btns button').first()
  if (await btn.count() && await btn.isVisible().catch(() => false)) await btn.click({ timeout: 2000 }).catch(() => {})
}

let loggedIn = false
if (fs.existsSync(stateFile)) {
  await page.goto(BASE + '/', { waitUntil: 'networkidle', timeout: 60000 })
  if (!page.url().includes('/login')) loggedIn = true
}
if (!loggedIn) {
  await page.goto(BASE + '/', { waitUntil: 'networkidle', timeout: 60000 })
  await page.waitForSelector('input[placeholder="请输入验证码"]', { timeout: 20000 })
  for (let ans = 0; ans <= 100; ans++) {
    await dismiss()
    await page.fill('input[placeholder="请输入用户名/身份证号码/手机号码"]', 'zsbase')
    await page.fill('input[placeholder="请输入用户密码"]', 'ZS001Aa!')
    await page.fill('input[placeholder="请输入验证码"]', String(ans))
    await page.getByRole('button', { name: /登\s*录/ }).first().click({ timeout: 5000 }).catch(() => {})
    const t0 = Date.now()
    while (Date.now() - t0 < 2500) {
      if (!page.url().includes('/login')) { loggedIn = true; break }
      if (await page.locator('.el-message-box__wrapper').isVisible().catch(() => false)) break
      await page.waitForTimeout(100)
    }
