  }
}
if (!loggedIn) { console.log('LOGIN_FAILED'); await browser.close(); process.exit(1) }
await context.storageState({ path: stateFile })
fs.writeFileSync(`${TMP}/cookies.json`, JSON.stringify(await context.cookies()))
console.log('STATE_SAVED')

const target = BASE + '/#/spfzjjg/zjjg/ACCOUNT_OPEN/account/add?formMode=add&backUrl=%2Fspfzjjg%2Fzjjg%2FACCOUNT_OPEN%2Faccount'
for (const vp of [{ w: 1798, h: 949 }, { w: 1366, h: 768 }, { w: 1280, h: 720 }, { w: 1093, h: 614 }, { w: 1024, h: 600 }]) {
  await page.setViewportSize({ width: vp.w, height: vp.h })
  await page.goto(target, { waitUntil: 'networkidle', timeout: 60000 })
  await page.waitForTimeout(1800)
  const injected = await page.evaluate(() => {
    const root = document.querySelector('#app')?.__vue__
    if (!root) return 'no-root'
    const stack = [root]; let found = null
    while (stack.length) {
      const vm = stack.pop()
      if (vm && typeof vm.showVisionOfBank === 'function') { found = vm; break }
      ;((vm && vm.$children) || []).forEach(c => stack.push(c))
    }
    if (!found) return 'no-vm'
    if (!found.form.bankName) found.form.bankName = '中国建设银行苏州分行营业部'
    if (!found.form.bankId) found.form.bankId = '1'
    return 'ok'
  })
  await page.waitForTimeout(400)
  try { await page.locator('input[placeholder="点击选择开户网点"]').first().click({ timeout: 8000 }) } catch (e) { console.log('CLICK_ERR', vp, String(e).slice(0, 100)) }
  await page.waitForTimeout(2200)
  const m = await page.evaluate(() => {
    const wrap = document.querySelector('.el-dialog__wrapper.zs-dialog.zs-select-dialog')
    if (!wrap) return { error: 'no-dialog' }
    const dlg = wrap.querySelector('.el-dialog')
    const body = wrap.querySelector('.el-dialog__body')
    const pag = wrap.querySelector('.zs-pagination') || wrap.querySelector('.el-pagination')
    const r = pag ? pag.getBoundingClientRect() : null
    const b = body ? body.getBoundingClientRect() : null
    return {
      cls: /table-scroll/.test(wrap.className),
      dialogH: dlg ? Math.round(dlg.getBoundingClientRect().height) : null,
      dialogTop: dlg ? Math.round(dlg.getBoundingClientRect().top) : null,
      dialogBottom: dlg ? Math.round(dlg.getBoundingClientRect().bottom) : null,
      bodySH: body?.scrollHeight, bodyCH: body?.clientHeight,
      bodyOverflowY: body ? getComputedStyle(body).overflowY : null,
      pagTop: r ? Math.round(r.top) : null, pagBottom: r ? Math.round(r.bottom) : null,
      pagInView: r ? (r.bottom <= innerHeight + 1 && r.top >= 0) : null,
      pagInDialog: r && b ? (r.bottom <= b.bottom + 1) : null,
      vh: innerHeight
    }
  })
  console.log('VP', JSON.stringify(vp), injected, JSON.stringify(m))
  if (vp.w === 1366 || vp.w === 1093) await page.screenshot({ path: `${TMP}/repro-${vp.w}x${vp.h}.png` })
}
await browser.close()

